<?php
declare(strict_types=1);
namespace App\Controller;
use App\Entity\SavedFilter; use App\Entity\User; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\JsonResponse; use Symfony\Component\HttpFoundation\Request; use Symfony\Component\Routing\Attribute\Route; use Symfony\Component\Uid\Uuid;
final class SavedFilterController extends AbstractController
{
 #[Route('/api/saved-filters', methods:['GET','POST'])] public function collection(Request $r, EntityManagerInterface $em): JsonResponse { $u=$this->user(); if ($r->isMethod('GET')) return $this->json(array_map(fn(SavedFilter $f)=>['id'=>(string)$f->getId(),'name'=>$f->getName(),'filters'=>$f->getFilters()],$em->getRepository(SavedFilter::class)->findBy(['user'=>$u],['name'=>'ASC']))); $p=$this->payload($r); $f=new SavedFilter($u,(string)($p['name']??''),$this->filters($p['filters']??[])); $em->persist($f); $em->flush(); return $this->json(['id'=>(string)$f->getId()],201); }
 #[Route('/api/saved-filters/{id}', methods:['PATCH','DELETE'])] public function item(string $id, Request $r, EntityManagerInterface $em): JsonResponse { try{$f=$em->getRepository(SavedFilter::class)->find(Uuid::fromString($id));}catch(\InvalidArgumentException){$f=null;} if(!$f instanceof SavedFilter || !$f->getUser()->getId()->equals($this->user()->getId())) throw $this->createNotFoundException(); if($r->isMethod('DELETE')){$em->remove($f);$em->flush();return $this->json(null,204);} $p=$this->payload($r); if(isset($p['name']))$f->rename((string)$p['name']); $em->flush(); return $this->json(['id'=>(string)$f->getId(),'name'=>$f->getName(),'filters'=>$f->getFilters()]); }
 private function user(): User {$u=$this->getUser();if(!$u instanceof User)throw $this->createAccessDeniedException();return $u;} private function payload(Request $r): array { if(!$this->isCsrfTokenValid('saved-filter',$r->headers->get('X-CSRF-Token')))throw $this->createAccessDeniedException(); try{$p=json_decode($r->getContent(),true,16,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new \InvalidArgumentException('JSON invalide.');} return is_array($p)?$p:[];} private function filters(mixed $v): array { if(!is_array($v))throw new \InvalidArgumentException('Filtres invalides.'); return array_filter($v,fn($x)=>is_scalar($x)||null===$x); }
}
